with valid as (select *, last_day(launch_date) as launch_date_month_end, coalesce(brand, 'N/A') as brand_filled from products where launch_date > to_date('2023-04-20') and supplier_id is not null) select s.*, latest.inventory_last_restock, latest.inventory_quantity from valid s left join lateral (select c.last_restock as inventory_last_restock, c.quantity as inventory_quantity from inventory c where c.product_id = s.id order by c.quantity desc, c.id desc limit 1) latest on true;
